import unittest
from app.config import LOG_LEVEL, resolve_timeout

class ConfigTest(unittest.TestCase):
    def test_none_uses_default(self):
        self.assertEqual(resolve_timeout(None), 30)

    def test_zero_is_explicit(self):
        self.assertEqual(resolve_timeout(0), 0)

    def test_positive_is_preserved(self):
        self.assertEqual(resolve_timeout(7), 7)

    def test_unrelated_config(self):
        self.assertEqual(LOG_LEVEL, 'info')
